package com.hbm.client.radar;
import api.hbm.entity.RadarEntry;import com.hbm.client.gui.LegacyScreen;import com.hbm.machine.radar.*;import com.mojang.blaze3d.systems.RenderSystem;import com.mojang.blaze3d.vertex.*;import java.util.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.renderer.GameRenderer;import net.minecraft.client.resources.language.I18n;import net.minecraft.client.resources.sounds.SimpleSoundInstance;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.sounds.SoundEvents;import net.neoforged.neoforge.network.PacketDistributor;import org.lwjgl.glfw.GLFW;
/** Original216x234 radar display, one40000pixelmap batch/source scanquad/13spriteblips and1..8link commands. */
public final class RadarScreen extends LegacyScreen{public static final ResourceLocation TEXTURE=RadarContent.id("textures/gui/machine/gui_radar_nt.png");private final RadarBlockEntity radar;private int left,top,lastMouseX,lastMouseY;private static final int[] BUTTON_Y={88,98,108,118,128,138,158,178};private static final String[] KEYS={"missiles","shells","players","smart","red","map","gui1","clear"},TOOLTIPS={"radar.detectMissiles","radar.detectShells","radar.detectPlayers","radar.smartMode","radar.redMode","radar.showMap","radar.toggleGui","radar.clearMap"};public RadarScreen(RadarBlockEntity radar){super(Component.translatable("container.radar"));this.radar=radar;}@Override protected void init(){super.init();left=(width-216)/2;top=(height-234)/2;}private boolean over(double x,double y,int ox,int oy,int w,int h){return left+ox<=x&&left+ox+w>x&&top+oy<y&&top+oy+h>=y;}private void send(CompoundTag data){PacketDistributor.sendToServer(new RadarControl(radar.getBlockPos(),data));}@Override public boolean mouseClicked(double x,double y,int button){for(int i=0;i<KEYS.length;i++)if(over(x,y,-10,BUTTON_Y[i],8,8)){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1));var tag=new CompoundTag();tag.putBoolean(KEYS[i],true);send(tag);return true;}return super.mouseClicked(x,y,button);}
 @Override public void render(GuiGraphics g,int x,int y,float partial){renderBackground(g,x,y,partial);background(g,partial);foreground(g,x,y);lastMouseX=x;lastMouseY=y;}private void blit(GuiGraphics g,int x,int y,int u,int v,int w,int h){g.blit(TEXTURE,left+x,top+y,u,v,w,h,256,256);}private int consumption(){return radar.clientConsumption>0?radar.clientConsumption:RadarConfig.consumption;}
 private void background(GuiGraphics g,float partial){blit(g,0,0,0,0,216,234);blit(g,-14,84,224,0,14,66);blit(g,-14,154,224,66,14,36);if(radar.power>0)blit(g,8,221,0,234,(int)(radar.power*200/radar.getMaxPower()),16);boolean[] states={radar.scanMissiles,radar.scanShells,radar.scanPlayers,radar.smartMode,radar.redMode,radar.showMap};for(int i=0;i<states.length;i++)if(states[i]^(radar.jammed&&radar.getLevel().random.nextBoolean()))blit(g,-10,BUTTON_Y[i],238,4+i*10,8,8);if(radar.power<consumption())return;if(radar.jammed){for(int i=0;i<5;i++)for(int j=0;j<5;j++)blit(g,8+i*40,17+j*40,216,118+radar.getLevel().random.nextInt(81),40,40);return;}if(radar.showMap){g.flush();RenderSystem.setShader(GameRenderer::getPositionColorShader);var out=Tesselator.getInstance().begin(VertexFormat.Mode.QUADS,DefaultVertexFormat.POSITION_COLOR);var pose=g.pose().last().pose();for(int i=0;i<40000;i++){byte height=radar.map[i];if(height<=0)continue;int xx=left+8+i%200,yy=top+17+i/200,green=(height-50)*255/78;out.addVertex(pose,xx,yy+1,0).setColor(0,green,0,255);out.addVertex(pose,xx+1,yy+1,0).setColor(0,green,0,255);out.addVertex(pose,xx+1,yy,0).setColor(0,green,0,255);out.addVertex(pose,xx,yy,0).setColor(0,green,0,255);}var mesh=out.build();if(mesh!=null)BufferUploader.drawWithShader(mesh);}scan(g,partial);for(var entry:radar.entries){double xx=(entry.posX-radar.getBlockPos().getX())/((double)radar.range()*2+1)*192-4,yy=(entry.posZ-radar.getBlockPos().getZ())/((double)radar.range()*2+1)*192-4;g.pose().pushPose();g.pose().translate(left+108+xx,top+117+yy,0);g.blit(TEXTURE,0,0,216,entry.blipLevel*8,8,8,256,256);g.pose().popPose();}}
 private void scan(GuiGraphics g,float partial){float rot=(float)-Math.toRadians(radar.prevRotation+(radar.rotation-radar.prevRotation)*partial+180);var tr=com.hbm.bomb.nuclear.LegacyVector.createVectorHelper(100,0,0);var tl=com.hbm.bomb.nuclear.LegacyVector.createVectorHelper(100,0,0);var bl=com.hbm.bomb.nuclear.LegacyVector.createVectorHelper(0,-5,0);tr.rotateAroundZ(rot);tl.rotateAroundZ(rot+.25F);bl.rotateAroundZ(rot);float trX=(float)tr.xCoord,trY=(float)tr.yCoord,tlX=(float)tl.xCoord,tlY=(float)tl.yCoord,blX=(float)bl.xCoord,blY=(float)bl.yCoord;g.flush();RenderSystem.setShader(GameRenderer::getPositionColorShader);RenderSystem.enableBlend();RenderSystem.defaultBlendFunc();var out=Tesselator.getInstance().begin(VertexFormat.Mode.QUADS,DefaultVertexFormat.POSITION_COLOR);var p=g.pose().last().pose();out.addVertex(p,left+108,top+117,0).setColor(0,255,0,0);out.addVertex(p,left+108+trX,top+117+trY,0).setColor(0,255,0,255);out.addVertex(p,left+108+tlX,top+117+tlY,0).setColor(0,255,0,0);out.addVertex(p,left+108+blX,top+117+blY,0).setColor(0,255,0,0);BufferUploader.drawWithShader(out.buildOrThrow());RenderSystem.disableBlend();}
 private void foreground(GuiGraphics g,int x,int y){if(over(x,y,8,221,200,7))g.renderTooltip(font,Component.literal(com.hbm.item.battery.BatteryItem.shortNumber(radar.power)+"/"+com.hbm.item.battery.BatteryItem.shortNumber(radar.getMaxPower())+"HE"),x,y);for(int i=0;i<KEYS.length;i++)if(over(x,y,-10,BUTTON_Y[i],8,8))g.renderComponentTooltip(font,Arrays.stream(I18n.get(TOOLTIPS[i]).split(java.util.regex.Pattern.quote("$"),-1)).map(Component::literal).map(c->(Component)c).toList(),x,y);for(var e:radar.entries){int xx=left+(int)((e.posX-radar.getBlockPos().getX())/((double)radar.range()*2+1)*192)+108,yy=top+(int)((e.posZ-radar.getBlockPos().getZ())/((double)radar.range()*2+1)*192)+117;if(x+5>xx&&x-4<=xx&&y+5>yy&&y-4<=yy){g.renderComponentTooltip(font,List.of(Component.literal(I18n.get(e.unlocalizedName)),Component.literal(e.posX+" / "+e.posZ),Component.translatable("gui.hbm.radar.target_altitude",e.posY)),xx,yy);return;}}if(over(x,y,8,17,200,200)){int tx=(int)((lastMouseX-left-108)*((double)radar.range()*2+1)/192+radar.getBlockPos().getX()),tz=(int)((lastMouseY-top-117)*((double)radar.range()*2+1)/192+radar.getBlockPos().getZ());g.renderTooltip(font,Component.literal(tx+" / "+tz),lastMouseX,lastMouseY);}}
 @Override public boolean keyPressed(int key,int scan,int modifiers){if(key==GLFW.GLFW_KEY_ESCAPE||minecraft.options.keyInventory.matches(key,scan)){onClose();return true;}return super.keyPressed(key,scan,modifiers);}@Override public boolean charTyped(char c,int modifiers){if(c<'1'||c>'8'||!over(lastMouseX,lastMouseY,8,17,200,200))return super.charTyped(c,modifiers);int link=c-'1';var tag=new CompoundTag();tag.putInt("link",link);for(var e:radar.entries){int x=left+(int)((e.posX-radar.getBlockPos().getX())/((double)radar.range()*2+1)*192)+108,z=top+(int)((e.posZ-radar.getBlockPos().getZ())/((double)radar.range()*2+1)*192)+117;if(lastMouseX+5>x&&lastMouseX-4<=x&&lastMouseY+5>z&&lastMouseY-4<=z){tag.putInt("launchEntity",e.entityID);send(tag);return true;}}tag.putInt("launchPosX",(int)((lastMouseX-left-108)*((double)radar.range()*2+1)/192+radar.getBlockPos().getX()));tag.putInt("launchPosZ",(int)((lastMouseY-top-117)*((double)radar.range()*2+1)/192+radar.getBlockPos().getZ()));send(tag);return true;}@Override public boolean isPauseScreen(){return false;}@Override public void tick(){if(minecraft.player==null||!minecraft.player.isAlive())onClose();}}
